INSERT IGNORE INTO `subcategories` (`category_id`, `name`, `name_en`, `slug`) SELECT c.`id`, 'AI-асистенти', 'AI Assistants', 'ai-assistants' FROM `categories` c WHERE c.`slug` = 'productivity' LIMIT 1;

