-- Microsoft Copilot — AI-асистенти
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'copilot.microsoft.com' OR LOWER(`name`) = LOWER('Microsoft Copilot'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Microsoft Copilot', NULL, 'https://copilot.microsoft.com', NULL, NULL, 'AI-асистент Microsoft: безкоштовний чат у вебі й застосунках, а з підпискою Microsoft 365 — допомога прямо у Word, Excel, PowerPoint, Outlook і Teams.', 'Microsoft''s AI assistant: a free chat on the web and in apps, and with a Microsoft 365 subscription, help right inside Word, Excel, PowerPoint, Outlook and Teams.', 'Microsoft Copilot — AI-асистент, вбудований в екосистему Microsoft. Безкоштовний Copilot Chat доступний у вебі, на Windows і в мобільних застосунках: він відповідає на запитання, пише й редагує тексти, працює з файлами та зображеннями. З підпискою Microsoft 365 Personal чи Family Copilot з''являється всередині Word, Excel, PowerPoint і Outlook — готує чернетки, підсумовує документи й листи, будує формули та слайди. Для бізнесу є Microsoft 365 Copilot з доступом до корпоративних даних і агентів: окремий модуль Copilot Business коштує $21 за користувача на місяць при річній оплаті (до грудня 2026 діє акційна ціна $18), а пакети Business Standard і Business Premium з Copilot — $23,50 і $32 за користувача на місяць.', 'Microsoft Copilot is an AI assistant built into the Microsoft ecosystem. The free Copilot Chat is available on the web, in Windows and in mobile apps: it answers questions, writes and edits text, and works with files and images. With a Microsoft 365 Personal or Family subscription, Copilot appears inside Word, Excel, PowerPoint and Outlook — drafting, summarising documents and emails, building formulas and slides. For businesses there is Microsoft 365 Copilot with access to company data and agents: the Copilot Business add-on costs $21 per user a month billed annually (a $18 promo price runs until December 2026), and the Business Standard and Business Premium bundles with Copilot cost $23.50 and $32 per user a month.', 'Безкоштовний AI-чат у вебі, Windows і мобільних застосунках
Copilot у Word, Excel, PowerPoint, Outlook і Teams
Підсумки документів, листів і зустрічей
Агенти та доступ до корпоративних даних у бізнес-версії', 'Free AI chat on the web, in Windows and mobile apps
Copilot in Word, Excel, PowerPoint, Outlook and Teams
Summaries of documents, emails and meetings
Agents and company data access in the business version', 'Користувачі Windows і Microsoft 365 — від домашніх користувачів до компаній, які працюють в Office.', 'Windows and Microsoft 365 users — from home users to companies that work in Office.', 'web,mobile,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
