-- Google Gemini — AI-асистенти
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gemini.google.com' OR LOWER(`name`) = LOWER('Google Gemini'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Google Gemini', NULL, 'https://gemini.google.com', NULL, NULL, 'AI-асистент Google: чат, глибоке дослідження, генерація зображень і відео, голосовий режим Gemini Live та інтеграція з Gmail, Документами й іншими сервісами Google.', 'Google''s AI assistant: chat, Deep Research, image and video generation, the Gemini Live voice mode and integration with Gmail, Docs and other Google services.', 'Google Gemini — AI-асистент від Google, доступний у вебі та в мобільних застосунках. Він веде діалог, пише й редагує тексти, аналізує файли, проводить глибоке дослідження з джерелами (Deep Research), генерує зображення, а в платних тарифах — і відео. Режим Gemini Live дає змогу говорити з асистентом голосом, а Canvas і Gems допомагають працювати з документами та власними налаштованими ботами. Gemini інтегрований у Gmail, Документи, Диск та інші сервіси Google. Безкоштовний тариф включає 15 ГБ сховища; платні Google AI Plus, AI Pro і AI Ultra розширюють ліміти, дають доступ до найпотужніших моделей і більше сховища. В Україні ціни такі: AI Plus — ₴224,99, AI Pro — ₴909,99, AI Ultra — від ₴4 599 на місяць.', 'Google Gemini is Google''s AI assistant, available on the web and in mobile apps. It holds conversations, writes and edits text, analyses files, runs in-depth research with sources (Deep Research), generates images and, on paid plans, video. Gemini Live lets you talk to the assistant by voice, while Canvas and Gems help you work on documents and with your own custom bots. Gemini is integrated into Gmail, Docs, Drive and other Google services. The free plan includes 15 GB of storage; the paid Google AI Plus, AI Pro and AI Ultra plans raise limits, unlock the most capable models and add more storage. In Ukraine the prices are ₴224.99 for AI Plus, ₴909.99 for AI Pro and from ₴4,599 a month for AI Ultra.', 'Чат, Deep Research і Canvas
Генерація зображень і відео
Голосовий режим Gemini Live
Інтеграція з Gmail, Документами й Диском
Власні боти Gems', 'Chat, Deep Research and Canvas
Image and video generation
Gemini Live voice mode
Integration with Gmail, Docs and Drive
Custom Gems bots', 'Усі, хто користується сервісами Google і хоче AI-асистента для навчання, роботи й повсякденних задач.', 'Anyone who uses Google services and wants an AI assistant for study, work and everyday tasks.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
