-- Monica — AI-асистенти
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'monica.im' OR LOWER(`name`) = LOWER('Monica'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Monica', NULL, 'https://monica.im', NULL, NULL, 'AI-асистент у браузері та застосунках: чат з провідними моделями, підсумки сторінок і відео, переклад, написання текстів, генерація зображень і AI-агент.', 'An AI assistant in your browser and apps: chat with leading models, page and video summaries, translation, writing, image generation and an AI agent.', 'Monica — універсальний AI-асистент, що працює як розширення браузера, веб-застосунок, настільна та мобільна програма. На будь-якій сторінці він підсумовує текст і відео, перекладає, пояснює, допомагає написати чи переписати текст і відповісти на лист; є ChatPDF, генерація зображень і відео, глибоке дослідження, створення презентацій та агент, що виконує дії в браузері. В одній підписці доступні моделі GPT, Claude, Gemini та інші. Тарифи (річна оплата): Free; Pro — $99 на рік (1 500 розширених кредитів на місяць); Max — $299 на рік (4 500 кредитів, зараз діє знижка до $199); Ultra — $995 на рік (20 000 кредитів).', 'Monica is an all-in-one AI assistant that works as a browser extension, web app, desktop and mobile app. On any page it summarises text and video, translates, explains, helps you write or rewrite text and reply to emails; there is also ChatPDF, image and video generation, deep research, slide creation and an agent that performs actions in the browser. GPT, Claude, Gemini and other models are available in one subscription. Plans (billed yearly): Free; Pro at $99 a year (1,500 advanced credits a month); Max at $299 a year (4,500 credits, currently discounted to $199); Ultra at $995 a year (20,000 credits).', 'Розширення браузера, веб, настільна й мобільна версії
Підсумки сторінок, відео та PDF
Переклад і допомога з написанням текстів
Генерація зображень і відео, презентації
AI-агент у браузері', 'Browser extension, web, desktop and mobile versions
Summaries of pages, videos and PDFs
Translation and writing help
Image and video generation, slide decks
AI agent in the browser', 'Студенти, офісні працівники й контент-мейкери, яким потрібен AI під рукою на будь-якому сайті.', 'Students, office workers and content creators who want AI at hand on any website.', 'web,mobile,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
