-- Sider — AI-асистенти
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sider.ai' OR LOWER(`name`) = LOWER('Sider'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Sider', NULL, 'https://sider.ai', NULL, NULL, 'AI-бічна панель для браузера: чат з GPT, Claude, Gemini та іншими моделями, підсумки й переклад сторінок і PDF, автоматизація дій у браузері та генерація контенту.', 'An AI sidebar for your browser: chat with GPT, Claude, Gemini and other models, summaries and translation of pages and PDFs, browser task automation and content generation.', 'Sider — AI-асистент у вигляді бічної панелі браузера, а також веб- і мобільний застосунок. У режимі чату він відповідає на запитання з використанням провідних моделей, підсумовує довгі статті, перекладає сторінки, PDF і зображення та пояснює складні поняття. Режим Hand автоматизує дії в браузері: заповнює форми, порівнює ціни, збирає інформацію з кількох сайтів і розбирає пошту Gmail. Є інструменти для зміни будь-якої вебсторінки, генерації зображень, відео й слайдів та база знань Wisebase. Усі тарифи мають однаковий набір функцій і відрізняються кількістю кредитів і потужністю хмарного комп''ютера: Nano — $100 на рік, Lite — $250, Pro — $500, Max — $1 000 на рік.', 'Sider is an AI assistant in the form of a browser sidebar, plus a web and mobile app. In chat mode it answers questions using leading models, summarises long articles, translates pages, PDFs and images and explains complex concepts. Hand mode automates browser actions: filling in forms, comparing prices, gathering information across sites and organising your Gmail inbox. There are tools to change any web page, generate images, video and slides, and a Wisebase knowledge base. All plans include the same features and differ in credits and cloud computer power: Nano at $100 a year, Lite at $250, Pro at $500 and Max at $1,000 a year.', 'Бічна панель з провідними моделями в будь-якому сайті
Підсумки й переклад сторінок, PDF і зображень
Автоматизація дій у браузері (Hand)
Генерація зображень, відео й слайдів
База знань Wisebase', 'Sidebar with leading models on any website
Summaries and translation of pages, PDFs and images
Browser task automation (Hand)
Image, video and slide generation
Wisebase knowledge base', 'Люди, які багато читають і працюють у браузері: студенти, дослідники, маркетологи.', 'People who read and work in the browser a lot: students, researchers and marketers.', 'web,mobile,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
