INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Merlin', NULL, 'https://www.getmerlin.in', NULL, NULL, 'AI-асистент у розширенні браузера та застосунках: чат з різними моделями, підсумки відео й сторінок, допомога з листами й текстами просто на сайті, де ви працюєте.', 'An AI assistant in a browser extension and apps: chat with various models, video and page summaries, and help with emails and text right on the site you are using.', 'Merlin — AI-асистент, який працює як розширення Chrome, веб-застосунок і мобільна програма. Він дає доступ до кількох провідних моделей в одному чаті, підсумовує відео YouTube і вебсторінки, допомагає писати й редагувати листи, пости та тексти прямо на сайтах і відповідає на запитання з пошуком в інтернеті. Безкоштовний план має обмежену кількість запитів; Pro коштує $228 на рік (≈$19 на місяць) з чесним лімітом використання; Teams — $180 на рік за користувача (≈$15 на місяць).', 'Merlin is an AI assistant that works as a Chrome extension, web app and mobile app. It gives access to several leading models in one chat, summarises YouTube videos and web pages, helps write and edit emails, posts and text right on websites and answers questions with web search. The free plan has a limited number of queries; Pro costs $228 a year (≈$19 a month) with a fair-use limit; Teams costs $180 a year per user (≈$15 a month).', 'Кілька провідних моделей в одному чаті
Підсумки відео YouTube і вебсторінок
Допомога з листами й текстами на будь-якому сайті
Відповіді з пошуком в інтернеті', 'Several leading models in one chat
YouTube video and web page summaries
Help with emails and text on any website
Answers with web search', 'Студенти, фрілансери й офісні працівники, які хочуть AI-помічника просто в браузері.', 'Students, freelancers and office workers who want an AI helper right in the browser.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
