INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'MaxAI', NULL, 'https://www.maxai.co', NULL, NULL, 'AI-розширення для Chrome і Edge: одним кліком пише, покращує, перекладає й підсумовує будь-який текст на сайті, дає чат з GPT, Claude, Gemini та іншими моделями.', 'An AI extension for Chrome and Edge: with one click it writes, improves, translates and summarises any text on a website and gives you chat with GPT, Claude, Gemini and other models.', 'MaxAI — AI-асистент у вигляді розширення для Chrome та Edge і веб-застосунку. Виділіть текст на будь-якому сайті — і він його перепише, виправить граматику, перекладе, пояснить, підсумує чи допоможе відповісти. У бічній панелі доступний чат з моделями GPT, Claude, Gemini, Grok, Llama і DeepSeek, пошук в інтернеті, робота з PDF і відео та генерація зображень. Сервісом користуються понад мільйон людей і 2 000 команд. Є безкоштовний тариф; Pro коштує $30 на місяць або $12 на місяць при річній оплаті.', 'MaxAI is an AI assistant in the form of a Chrome and Edge extension and a web app. Select text on any website and it will rewrite it, fix grammar, translate, explain, summarise or help you reply. The sidebar offers chat with GPT, Claude, Gemini, Grok, Llama and DeepSeek models, web search, PDF and video chat and image generation. More than a million people and 2,000 teams use it. There is a free plan; Pro costs $30 a month or $12 a month billed yearly.', 'Дії з виділеним текстом на будь-якому сайті
Чат з GPT, Claude, Gemini, Grok, Llama, DeepSeek
Переклад, граматика й підсумки
Робота з PDF і відео, генерація зображень', 'Actions on selected text on any website
Chat with GPT, Claude, Gemini, Grok, Llama, DeepSeek
Translation, grammar and summaries
PDF and video chat, image generation', 'Ті, хто багато пише й читає в браузері: маркетологи, підтримка клієнтів, студенти.', 'People who write and read a lot in the browser: marketers, customer support and students.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'maxai.co' OR LOWER(`name`) = LOWER('MaxAI')) ORDER BY `id` LIMIT 1);
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE @pid IS NOT NULL AND c.`slug` = 'productivity' LIMIT 1;
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @pid IS NOT NULL AND c.`slug` = 'productivity' AND s.`slug` = 'ai-assistants' LIMIT 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'An AI extension for Chrome and Edge: with one click it writes, improves, translates and summarises any text on a website and gives you chat with GPT, Claude, Gemini and other models.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'MaxAI is an AI assistant in the form of a Chrome and Edge extension and a web app. Select text on any website and it will rewrite it, fix grammar, translate, explain, summarise or help you reply. The sidebar offers chat with GPT, Claude, Gemini, Grok, Llama and DeepSeek models, web search, PDF and video chat and image generation. More than a million people and 2,000 teams use it. There is a free plan; Pro costs $30 a month or $12 a month billed yearly.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'main_features', 'en', 'Actions on selected text on any website
Chat with GPT, Claude, Gemini, Grok, Llama, DeepSeek
Translation, grammar and summaries
PDF and video chat, image generation', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'target_audience', 'en', 'People who write and read a lot in the browser: marketers, customer support and students.', 'manual' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `plan_name_en`, `price`, `period`, `description`, `description_en`) SELECT @pid, 'Free', 'Free', 0.00, 'free', 'Базові функції з обмеженнями', 'Basic features with limits' FROM DUAL WHERE @new = 1;
SET @plan = IF(@new = 1, (SELECT `id` FROM `pricing_plans` WHERE `product_id` = @pid AND `plan_name` = 'Free' ORDER BY `id` DESC LIMIT 1), NULL);
INSERT IGNORE INTO `pricing_plan_translations` (`plan_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @plan, 'plan_name', 'en', 'Free', 'manual' FROM DUAL WHERE @plan IS NOT NULL;
INSERT IGNORE INTO `pricing_plan_translations` (`plan_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @plan, 'description', 'en', 'Basic features with limits', 'manual' FROM DUAL WHERE @plan IS NOT NULL;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `plan_name_en`, `price`, `period`, `description`, `description_en`) SELECT @pid, 'Pro', 'Pro', 30.00, 'month', 'Необмежені розширені функції; $12/міс при річній оплаті', 'Unlimited advanced features; $12/mo billed yearly' FROM DUAL WHERE @new = 1;
SET @plan = IF(@new = 1, (SELECT `id` FROM `pricing_plans` WHERE `product_id` = @pid AND `plan_name` = 'Pro' ORDER BY `id` DESC LIMIT 1), NULL);
INSERT IGNORE INTO `pricing_plan_translations` (`plan_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @plan, 'plan_name', 'en', 'Pro', 'manual' FROM DUAL WHERE @plan IS NOT NULL;
INSERT IGNORE INTO `pricing_plan_translations` (`plan_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @plan, 'description', 'en', 'Unlimited advanced features; $12/mo billed yearly', 'manual' FROM DUAL WHERE @plan IS NOT NULL;

